import React, { useState } from 'react';
import { Wand2, AlertCircle } from 'lucide-react';

interface ScriptInputProps {
  onAnalyze: (script: string) => void;
  isAnalyzing: boolean;
}

export const ScriptInput: React.FC<ScriptInputProps> = ({ onAnalyze, isAnalyzing }) => {
  const [script, setScript] = useState<string>('');
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = () => {
    if (!script.trim()) {
      setError("Please enter a script first.");
      return;
    }
    setError(null);
    onAnalyze(script);
  };

  const sampleScript = `EXT. CITY STREET - NIGHT
Rain slicks the neon-lit pavement. A lone DETECTIVE (40s, trench coat) stands under a flickering streetlamp, lighting a cigarette.

INT. DINER - NIGHT
The Detective enters. The bell chimes. A TIRED WAITRESS looks up from the counter.

DETECTIVE
Coffee. Black.

The Waitress nods, pouring a steaming cup. The Detective stares out the window at a hovering drone scanning the crowd.`;

  return (
    <div className="max-w-3xl mx-auto space-y-6 animate-fade-in">
      <div className="text-center space-y-4 mb-10">
        <h2 className="text-4xl font-extrabold tracking-tight text-white sm:text-5xl">
          Bring your story to life.
        </h2>
        <p className="text-lg text-slate-400 max-w-2xl mx-auto">
          Paste your screenplay, video script, or even a rough idea below. 
          Our AI will break it down into scenes and generate professional storyboard frames instantly.
        </p>
      </div>

      <div className="bg-slate-800 rounded-2xl p-1 shadow-xl border border-slate-700 focus-within:ring-2 focus-within:ring-indigo-500 transition-all">
        <textarea
          value={script}
          onChange={(e) => setScript(e.target.value)}
          className="w-full h-96 bg-slate-900 rounded-xl p-6 text-slate-300 placeholder-slate-600 focus:outline-none resize-none font-mono text-sm leading-relaxed"
          placeholder="EXT. ALIEN PLANET - DAY..."
        />
      </div>

      {error && (
        <div className="flex items-center space-x-2 text-red-400 text-sm px-2">
          <AlertCircle className="w-4 h-4" />
          <span>{error}</span>
        </div>
      )}

      <div className="flex items-center justify-between pt-2">
        <button
          onClick={() => setScript(sampleScript)}
          className="text-sm text-slate-500 hover:text-indigo-400 transition-colors"
        >
          Use sample script
        </button>

        <button
          onClick={handleSubmit}
          disabled={isAnalyzing}
          className={`flex items-center space-x-2 px-8 py-3 rounded-xl font-semibold text-white transition-all transform hover:scale-105 active:scale-95 shadow-lg shadow-indigo-500/25 ${
            isAnalyzing
              ? 'bg-slate-700 cursor-wait'
              : 'bg-indigo-600 hover:bg-indigo-500'
          }`}
        >
          {isAnalyzing ? (
            <>
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              <span>Analyzing...</span>
            </>
          ) : (
            <>
              <Wand2 className="w-5 h-5" />
              <span>Generate Storyboard</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
};

import React from 'react';
import { ScriptScene } from '../types';
import { FrameCard } from './FrameCard';
import { Download, ArrowLeft, Layers } from 'lucide-react';

interface StoryboardProps {
  scenes: ScriptScene[];
  onBack: () => void;
  onUpdateScene: (id: string, updates: Partial<ScriptScene>) => void;
  onGenerateImage: (id: string) => void;
}

export const Storyboard: React.FC<StoryboardProps> = ({
  scenes,
  onBack,
  onUpdateScene,
  onGenerateImage,
}) => {

  const handleGenerateAll = () => {
    // Trigger generation for all scenes that don't have an image
    scenes.forEach((scene, index) => {
      if (!scene.image_url && !scene.is_generating) {
        // Stagger requests slightly to avoid browser/network choke, although Gemini handles concurrency well enough
        setTimeout(() => {
          onGenerateImage(scene.id);
        }, index * 200);
      }
    });
  };

  const completedCount = scenes.filter(s => s.image_url).length;
  const progress = Math.round((completedCount / scenes.length) * 100);

  return (
    <div className="space-y-8 animate-fade-in-up">
      {/* Header Toolbar */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-800/50 p-4 rounded-2xl border border-slate-700 backdrop-blur-sm sticky top-20 z-40">
        <div className="flex items-center space-x-4">
          <button
            onClick={onBack}
            className="p-2 hover:bg-slate-700 rounded-lg transition-colors text-slate-400 hover:text-white"
            title="Back to Script"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
              <Layers className="w-5 h-5 text-indigo-400" />
              Storyboard
            </h2>
            <p className="text-xs text-slate-400">
              {completedCount} of {scenes.length} frames rendered
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {progress < 100 && (
            <div className="hidden sm:block w-32 h-2 bg-slate-700 rounded-full overflow-hidden">
              <div 
                className="h-full bg-indigo-500 transition-all duration-500"
                style={{ width: `${progress}%` }}
              />
            </div>
          )}

          <button
            onClick={handleGenerateAll}
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-sm font-medium transition-colors shadow-lg shadow-indigo-500/20"
          >
            Generate All Images
          </button>

          <button
            onClick={() => window.print()}
            className="px-4 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-2"
          >
            <Download className="w-4 h-4" />
            <span className="hidden sm:inline">Export PDF</span>
          </button>
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 pb-20">
        {scenes.map((scene) => (
          <FrameCard
            key={scene.id}
            scene={scene}
            onUpdate={(updates) => onUpdateScene(scene.id, updates)}
            onGenerate={() => onGenerateImage(scene.id)}
          />
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ScriptScene } from '../types';
import { RefreshCw, Edit2, Image as ImageIcon, Save, X } from 'lucide-react';

interface FrameCardProps {
  scene: ScriptScene;
  onUpdate: (updates: Partial<ScriptScene>) => void;
  onGenerate: () => void;
}

export const FrameCard: React.FC<FrameCardProps> = ({ scene, onUpdate, onGenerate }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editPrompt, setEditPrompt] = useState(scene.visual_prompt);

  const handleSavePrompt = () => {
    onUpdate({ visual_prompt: editPrompt });
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setEditPrompt(scene.visual_prompt);
    setIsEditing(false);
  };

  return (
    <div className="bg-slate-800 rounded-xl overflow-hidden border border-slate-700 hover:border-indigo-500/50 transition-all duration-300 shadow-lg group flex flex-col h-full">
      {/* Header */}
      <div className="px-4 py-3 bg-slate-900/50 border-b border-slate-700 flex justify-between items-center">
        <span className="text-xs font-bold text-indigo-400 uppercase tracking-wider">
          Scene {scene.scene_number}
        </span>
        <div className="flex gap-2">
           <button
             onClick={() => setIsEditing(!isEditing)}
             className="text-slate-400 hover:text-white transition-colors"
             title="Edit Prompt"
           >
             <Edit2 className="w-4 h-4" />
           </button>
        </div>
      </div>

      {/* Image Area */}
      <div className="relative aspect-video bg-slate-900 group-hover:bg-slate-950 transition-colors">
        {scene.image_url ? (
          <img
            src={scene.image_url}
            alt={`Scene ${scene.scene_number}`}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-600 p-6 text-center">
            {scene.is_generating ? (
              <div className="animate-pulse flex flex-col items-center">
                <div className="w-10 h-10 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin mb-4" />
                <span className="text-sm text-indigo-400 font-medium">Rendering...</span>
              </div>
            ) : (
              <>
                <ImageIcon className="w-12 h-12 mb-3 opacity-50" />
                <p className="text-sm">Ready to generate</p>
              </>
            )}
          </div>
        )}

        {/* Hover Overlay Action */}
        {!scene.is_generating && (
           <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-[1px]">
             <button
               onClick={onGenerate}
               className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-lg font-medium shadow-lg transform translate-y-4 group-hover:translate-y-0 transition-all duration-300 flex items-center gap-2"
             >
               <RefreshCw className="w-4 h-4" />
               {scene.image_url ? 'Regenerate' : 'Generate'}
             </button>
           </div>
        )}
      </div>

      {/* Content Area */}
      <div className="p-4 flex flex-col flex-grow space-y-3">
        {/* Narrative Description */}
        <p className="text-slate-300 text-sm leading-relaxed border-l-2 border-slate-600 pl-3 italic">
          "{scene.description}"
        </p>

        {/* Visual Prompt Editor */}
        <div className="mt-auto">
          {isEditing ? (
            <div className="space-y-2 mt-2">
              <label className="text-xs text-slate-500 font-semibold uppercase">Visual Prompt</label>
              <textarea
                value={editPrompt}
                onChange={(e) => setEditPrompt(e.target.value)}
                className="w-full bg-slate-900 rounded-lg p-3 text-xs text-slate-300 border border-indigo-500/50 focus:outline-none focus:ring-1 focus:ring-indigo-500 h-24 resize-none"
              />
              <div className="flex justify-end gap-2">
                <button 
                  onClick={handleCancelEdit}
                  className="p-1.5 text-slate-400 hover:text-white"
                >
                  <X className="w-4 h-4" />
                </button>
                <button 
                  onClick={handleSavePrompt}
                  className="p-1.5 text-indigo-400 hover:text-indigo-300"
                >
                  <Save className="w-4 h-4" />
                </button>
              </div>
            </div>
          ) : (
            <div className="group/prompt cursor-pointer" onClick={() => setIsEditing(true)}>
               <div className="flex justify-between items-baseline mb-1">
                 <span className="text-xs text-slate-500 font-semibold uppercase">Visual Prompt</span>
               </div>
               <p className="text-xs text-slate-500 line-clamp-3 hover:text-slate-400 transition-colors">
                 {scene.visual_prompt}
               </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, Bot, User } from 'lucide-react';
import { sendChatMessage } from '../services/geminiService';
import { ChatMessage, ScriptScene } from '../types';

interface AssistantProps {
  isOpen: boolean;
  onClose: () => void;
  contextData: ScriptScene[];
}

export const Assistant: React.FC<AssistantProps> = ({ isOpen, onClose, contextData }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hi! I can help you refine your script or suggest better visual prompts for your storyboard. What are you working on?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    // Prepare context
    const contextSummary = contextData.length > 0 
      ? `User has a storyboard with ${contextData.length} scenes. Scene 1 description: ${contextData[0].description}...` 
      : "User has not analyzed a script yet.";

    // Format history for API
    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    try {
      const responseText = await sendChatMessage(history, userMsg.text, contextSummary);
      setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, something went wrong." }]);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-y-0 right-0 w-full sm:w-96 bg-slate-900 border-l border-slate-700 shadow-2xl z-50 transform transition-transform duration-300 ease-in-out flex flex-col">
      <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-800/50">
        <h3 className="font-semibold text-white flex items-center gap-2">
          <Bot className="w-5 h-5 text-indigo-400" />
          AI Assistant
        </h3>
        <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
          <X className="w-5 h-5" />
        </button>
      </div>

      <div className="flex-grow overflow-y-auto p-4 space-y-4">
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] rounded-2xl p-3 text-sm ${
                msg.role === 'user'
                  ? 'bg-indigo-600 text-white rounded-br-none'
                  : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
              }`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-800 rounded-2xl p-3 rounded-bl-none border border-slate-700 flex items-center gap-2">
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce delay-100" />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce delay-200" />
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 border-t border-slate-700 bg-slate-900">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask for suggestions..."
            className="w-full bg-slate-800 text-white rounded-full pl-4 pr-12 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-600 rounded-full text-white disabled:opacity-50 hover:bg-indigo-500 transition-colors"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { ScriptInput } from './components/ScriptInput';
import { Storyboard } from './components/Storyboard';
import { Assistant } from './components/Assistant';
import { AppView, ScriptScene } from './types';
import { analyzeScript, generateSceneImage } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.SCRIPT_INPUT);
  const [scenes, setScenes] = useState<ScriptScene[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isAssistantOpen, setIsAssistantOpen] = useState(false);

  const handleAnalyzeScript = async (scriptText: string) => {
    setIsAnalyzing(true);
    try {
      const analyzedScenes = await analyzeScript(scriptText);
      setScenes(analyzedScenes);
      setView(AppView.BOARD_VIEW);
    } catch (error) {
      alert("Failed to analyze script. Please check your API key and try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleUpdateScene = (id: string, updates: Partial<ScriptScene>) => {
    setScenes(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleGenerateImage = async (id: string) => {
    const sceneIndex = scenes.findIndex(s => s.id === id);
    if (sceneIndex === -1) return;

    // Optimistic update: loading state
    const updatedScenes = [...scenes];
    updatedScenes[sceneIndex] = { ...updatedScenes[sceneIndex], is_generating: true };
    setScenes(updatedScenes);

    try {
      const prompt = updatedScenes[sceneIndex].visual_prompt;
      const imageUrl = await generateSceneImage(prompt);

      setScenes(prev => prev.map(s => 
        s.id === id 
          ? { ...s, image_url: imageUrl || undefined, is_generating: false } 
          : s
      ));
    } catch (error) {
      console.error(error);
      setScenes(prev => prev.map(s => 
        s.id === id ? { ...s, is_generating: false } : s
      ));
      // Optional: Show error toast
    }
  };

  return (
    <Layout onOpenAssistant={() => setIsAssistantOpen(true)}>
      {view === AppView.SCRIPT_INPUT && (
        <ScriptInput 
          onAnalyze={handleAnalyzeScript} 
          isAnalyzing={isAnalyzing} 
        />
      )}

      {view === AppView.BOARD_VIEW && (
        <Storyboard
          scenes={scenes}
          onBack={() => setView(AppView.SCRIPT_INPUT)}
          onUpdateScene={handleUpdateScene}
          onGenerateImage={handleGenerateImage}
        />
      )}

      <Assistant 
        isOpen={isAssistantOpen} 
        onClose={() => setIsAssistantOpen(false)}
        contextData={scenes}
      />
    </Layout>
  );
};

