  onGenerate: () => void;
}

export const FrameCard: React.FC<FrameCardProps> = ({ scene, onUpdate, onGenerate }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editPrompt, setEditPrompt] = useState(scene.visual_prompt);

  const handleSavePrompt = () => {
    onUpdate({ visual_prompt: editPrompt });
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setEditPrompt(scene.visual_prompt);
    setIsEditing(false);
  };

  const handleDownload = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (scene.image_url) {
      const link = document.createElement('a');
      link.href = scene.image_url;
      link.download = `storyboard-scene-${scene.scene_number}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  return (
    <div className="bg-slate-800 rounded-xl overflow-hidden border border-slate-700 hover:border-indigo-500/50 transition-all duration-300 shadow-lg group flex flex-col h-full print-break-inside-avoid print-bg-white print-text-black">
