  text: string;
}

import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { ScriptInput } from './components/ScriptInput';
import { Storyboard } from './components/Storyboard';
import { Assistant } from './components/Assistant';
import { AppView, ScriptScene } from './types';
import { analyzeScript, generateSceneImage } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.SCRIPT_INPUT);
  const [scenes, setScenes] = useState<ScriptScene[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isAssistantOpen, setIsAssistantOpen] = useState(false);

  const handleAnalyzeScript = async (scriptText: string) => {
    setIsAnalyzing(true);
    try {
      const analyzedScenes = await analyzeScript(scriptText);
      setScenes(analyzedScenes);
      setView(AppView.BOARD_VIEW);
    } catch (error) {
      alert("Failed to analyze script. Please check your API key and try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleUpdateScene = (id: string, updates: Partial<ScriptScene>) => {
    setScenes(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleGenerateImage = async (id: string) => {
    const sceneIndex = scenes.findIndex(s => s.id === id);
    if (sceneIndex === -1) return;

    // Optimistic update: loading state, clear previous errors
    setScenes(prev => prev.map(s => s.id === id ? { ...s, is_generating: true, error: undefined } : s));

    try {
      const scene = scenes.find(s => s.id === id);
      if (!scene) return;

      const imageUrl = await generateSceneImage(scene.visual_prompt);

      setScenes(prev => prev.map(s => 
        s.id === id 
          ? { ...s, image_url: imageUrl || undefined, is_generating: false } 
          : s
      ));
    } catch (error: any) {
      console.error(error);
      const errorMsg = JSON.stringify(error).includes("429") 
        ? "Rate limit exceeded" 
        : "Generation failed";

      setScenes(prev => prev.map(s => 
        s.id === id ? { ...s, is_generating: false, error: errorMsg } : s
      ));
    }
  };

  const handleGenerateAll = () => {
    const scenesToGenerate = scenes.filter(s => !s.image_url && !s.is_generating);
    if (scenesToGenerate.length === 0) return;

    // 1. Immediately set all targets to is_generating
    const idsToGenerate = new Set(scenesToGenerate.map(s => s.id));
    setScenes(prev => prev.map(s => 
      idsToGenerate.has(s.id) ? { ...s, is_generating: true, error: undefined } : s
    ));

    // 2. Process them with a significantly longer stagger to avoid 429 errors
    // 4000ms = 4 seconds per request = 15 requests per minute (safe for most tiers)
    scenesToGenerate.forEach((scene, index) => {
      setTimeout(async () => {
        try {
          const imageUrl = await generateSceneImage(scene.visual_prompt);
          setScenes(prev => prev.map(s => 
            s.id === scene.id 
              ? { ...s, image_url: imageUrl || undefined, is_generating: false } 
              : s
          ));
        } catch (error: any) {
          console.error(`Failed to generate scene ${scene.scene_number}:`, error);
          const errorMsg = JSON.stringify(error).includes("429") 
            ? "Rate limit exceeded" 
            : "Generation failed";

          setScenes(prev => prev.map(s => 
            s.id === scene.id ? { ...s, is_generating: false, error: errorMsg } : s
          ));
        }
      }, index * 4000); // 4000ms stagger
    });
  };

  return (
    <Layout onOpenAssistant={() => setIsAssistantOpen(true)}>
      {view === AppView.SCRIPT_INPUT && (
        <ScriptInput 
          onAnalyze={handleAnalyzeScript} 
          isAnalyzing={isAnalyzing} 
        />
      )}

      {view === AppView.BOARD_VIEW && (
        <Storyboard
          scenes={scenes}
          onBack={() => setView(AppView.SCRIPT_INPUT)}
          onUpdateScene={handleUpdateScene}
          onGenerateImage={handleGenerateImage}
          onGenerateAll={handleGenerateAll}
        />
      )}

      <Assistant 
        isOpen={isAssistantOpen} 
        onClose={() => setIsAssistantOpen(false)}
        contextData={scenes}
      />
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { ScriptScene } from '../types';
import { RefreshCw, Edit2, Image as ImageIcon, Save, X, Download, Loader2, AlertCircle } from 'lucide-react';

interface FrameCardProps {
  scene: ScriptScene;
  onUpdate: (updates: Partial<ScriptScene>) => void;
  onGenerate: () => void;
}

export const FrameCard: React.FC<FrameCardProps> = ({ scene, onUpdate, onGenerate }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editPrompt, setEditPrompt] = useState(scene.visual_prompt);

  const handleSavePrompt = () => {
    onUpdate({ visual_prompt: editPrompt });
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setEditPrompt(scene.visual_prompt);
    setIsEditing(false);
  };

  const handleDownload = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (scene.image_url) {
      const link = document.createElement('a');
      link.href = scene.image_url;
      link.download = `storyboard-scene-${scene.scene_number}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  return (
    <div className={`bg-slate-800 rounded-xl overflow-hidden border transition-all duration-300 shadow-lg group flex flex-col h-full print-break-inside-avoid print-bg-white print-text-black ${scene.error ? 'border-red-500/50' : 'border-slate-700 hover:border-indigo-500/50'}`}>
      {/* Header */}
      <div className="px-4 py-3 bg-slate-900/50 border-b border-slate-700 flex justify-between items-center print-bg-white">
        <span className={`text-xs font-bold uppercase tracking-wider print-text-black ${scene.error ? 'text-red-400' : 'text-indigo-400'}`}>
          Scene {scene.scene_number}
        </span>
        <div className="flex gap-2 no-print">
           <button
             onClick={() => setIsEditing(!isEditing)}
             className="text-slate-400 hover:text-white transition-colors"
             title="Edit Prompt"
           >
             <Edit2 className="w-4 h-4" />
           </button>
        </div>
      </div>

      {/* Image Area */}
      <div className="relative aspect-video bg-slate-900 group-hover:bg-slate-950 transition-colors print-bg-white overflow-hidden">
        {scene.image_url ? (
          <>
            <img
              src={scene.image_url}
              alt={`Scene ${scene.scene_number}`}
              className="w-full h-full object-cover"
            />
            {/* Download Button - Top Right Corner (Always Visible) */}
             {!scene.is_generating && (
              <button
                onClick={handleDownload}
                className="absolute top-2 right-2 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full backdrop-blur-sm transition-all z-10 no-print border border-white/10"
                title="Download Image"
              >
                <Download className="w-4 h-4" />
              </button>
            )}
          </>
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-600 p-6 text-center">
            {scene.is_generating ? (
              <div className="flex flex-col items-center animate-pulse">
                <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                <span className="text-sm text-indigo-400 font-medium">Rendering...</span>
              </div>
            ) : scene.error ? (
              <div className="flex flex-col items-center text-red-400 animate-in fade-in duration-300">
                <AlertCircle className="w-10 h-10 mb-2" />
                <p className="text-sm font-medium mb-3">{scene.error}</p>
                <button 
                  onClick={onGenerate} 
                  className="text-xs bg-red-500/10 hover:bg-red-500/20 text-red-300 px-4 py-2 rounded-full transition-colors border border-red-500/20 flex items-center gap-2"
                >
                  <RefreshCw className="w-3 h-3" /> Try Again
                </button>
              </div>
            ) : (
              <>
                <ImageIcon className="w-12 h-12 mb-3 opacity-50" />
                <p className="text-sm">Ready to generate</p>
              </>
            )}
          </div>
        )}

        {/* Loading Overlay for re-generation (if image exists but is regenerating) */}
        {scene.image_url && scene.is_generating && (
           <div className="absolute inset-0 bg-slate-900/80 z-20 flex flex-col items-center justify-center backdrop-blur-sm">
              <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
              <span className="text-sm text-indigo-400 font-medium">Updating...</span>
           </div>
        )}

        {/* Center Generate/Regenerate Button Overlay (Screen only) */}
        {!scene.is_generating && !scene.error && (
           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-[1px] no-print">
             <button
               onClick={onGenerate}
               className="bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-2.5 rounded-full font-medium shadow-lg transform translate-y-4 group-hover:translate-y-0 transition-all duration-300 flex items-center gap-2"
             >
               <RefreshCw className="w-4 h-4" />
               {scene.image_url ? 'Regenerate' : 'Generate'}
             </button>
           </div>
        )}
      </div>

      {/* Content Area */}
      <div className="p-4 flex flex-col flex-grow space-y-3">
        {/* Narrative Description */}
        <p className="text-slate-300 text-sm leading-relaxed border-l-2 border-slate-600 pl-3 italic print-text-black">
          "{scene.description}"
        </p>

        {/* Visual Prompt Editor */}
        <div className="mt-auto no-print">
          {isEditing ? (
            <div className="space-y-2 mt-2">
              <label className="text-xs text-slate-500 font-semibold uppercase">Visual Prompt</label>
              <textarea
                value={editPrompt}
                onChange={(e) => setEditPrompt(e.target.value)}
                className="w-full bg-slate-900 rounded-lg p-3 text-xs text-slate-300 border border-indigo-500/50 focus:outline-none focus:ring-1 focus:ring-indigo-500 h-24 resize-none"
              />
              <div className="flex justify-end gap-2">
                <button 
                  onClick={handleCancelEdit}
                  className="p-1.5 text-slate-400 hover:text-white"
                >
                  <X className="w-4 h-4" />
                </button>
                <button 
                  onClick={handleSavePrompt}
                  className="p-1.5 text-indigo-400 hover:text-indigo-300"
                >
                  <Save className="w-4 h-4" />
                </button>
              </div>
            </div>
          ) : (
            <div className="group/prompt cursor-pointer" onClick={() => setIsEditing(true)}>
               <div className="flex justify-between items-baseline mb-1">
                 <span className="text-xs text-slate-500 font-semibold uppercase">Visual Prompt</span>
               </div>
               <p className="text-xs text-slate-500 line-clamp-3 hover:text-slate-400 transition-colors">
                 {scene.visual_prompt}
               </p>
            </div>
          )}
        </div>

        {/* Print-only prompt display */}
        <div className="hidden print:block mt-2">
           <span className="text-xs font-bold uppercase text-gray-500">Visual Prompt:</span>
           <p className="text-xs text-black">{scene.visual_prompt}</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { ScriptInput } from './components/ScriptInput';
import { Storyboard } from './components/Storyboard';
import { Assistant } from './components/Assistant';
import { AppView, ScriptScene } from './types';
import { analyzeScript, generateSceneImage } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.SCRIPT_INPUT);
  const [scenes, setScenes] = useState<ScriptScene[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isAssistantOpen, setIsAssistantOpen] = useState(false);

  const handleAnalyzeScript = async (scriptText: string) => {
    setIsAnalyzing(true);
    try {
      const analyzedScenes = await analyzeScript(scriptText);
      setScenes(analyzedScenes);
      setView(AppView.BOARD_VIEW);
    } catch (error) {
      alert("Failed to analyze script. Please check your API key and try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleUpdateScene = (id: string, updates: Partial<ScriptScene>) => {
    setScenes(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleGenerateImage = async (id: string) => {
    const sceneIndex = scenes.findIndex(s => s.id === id);
    if (sceneIndex === -1) return;

    // Optimistic update: loading state, clear previous errors
    setScenes(prev => prev.map(s => s.id === id ? { ...s, is_generating: true, error: undefined } : s));

    try {
      const scene = scenes.find(s => s.id === id);
      if (!scene) return;

      const imageUrl = await generateSceneImage(scene.visual_prompt);

      setScenes(prev => prev.map(s => 
        s.id === id 
          ? { ...s, image_url: imageUrl || undefined, is_generating: false } 
          : s
      ));
    } catch (error: any) {
      console.error(error);
      const errStr = JSON.stringify(error) + (error?.message || '');
      const isRateLimit = errStr.includes("429") || errStr.includes("RESOURCE_EXHAUSTED");
      const errorMsg = isRateLimit ? "Rate limit exceeded. Wait 30s." : "Generation failed";

      setScenes(prev => prev.map(s => 
        s.id === id ? { ...s, is_generating: false, error: errorMsg } : s
      ));
    }
  };

  const handleGenerateAll = async () => {
    const scenesToGenerate = scenes.filter(s => !s.image_url && !s.is_generating);
    if (scenesToGenerate.length === 0) return;

    // 1. Immediately set all targets to is_generating so UI shows spinners
    const idsToGenerate = new Set(scenesToGenerate.map(s => s.id));
    setScenes(prev => prev.map(s => 
      idsToGenerate.has(s.id) ? { ...s, is_generating: true, error: undefined } : s
    ));

    // 2. Process sequentially to respect API rate limits
    // Using a for loop with await ensures we don't fire multiple requests at once
    for (let i = 0; i < scenesToGenerate.length; i++) {
      const scene = scenesToGenerate[i];

      try {
        const imageUrl = await generateSceneImage(scene.visual_prompt);

        setScenes(prev => prev.map(s => 
          s.id === scene.id 
            ? { ...s, image_url: imageUrl || undefined, is_generating: false } 
            : s
        ));
      } catch (error: any) {
        console.error(`Failed to generate scene ${scene.scene_number}:`, error);

        const errStr = JSON.stringify(error) + (error?.message || '');
        const isRateLimit = errStr.includes("429") || errStr.includes("RESOURCE_EXHAUSTED");
        const errorMsg = isRateLimit ? "Rate limit hit" : "Failed";

        setScenes(prev => prev.map(s => 
          s.id === scene.id ? { ...s, is_generating: false, error: errorMsg } : s
        ));
      }

      // 3. Add a significant delay between requests to recover quota
      // 6 seconds = 10 requests per minute max.
      if (i < scenesToGenerate.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 6000));
      }
    }
  };

  return (
    <Layout onOpenAssistant={() => setIsAssistantOpen(true)}>
      {view === AppView.SCRIPT_INPUT && (
        <ScriptInput 
          onAnalyze={handleAnalyzeScript} 
          isAnalyzing={isAnalyzing} 
        />
      )}

      {view === AppView.BOARD_VIEW && (
        <Storyboard
          scenes={scenes}
          onBack={() => setView(AppView.SCRIPT_INPUT)}
          onUpdateScene={handleUpdateScene}
          onGenerateImage={handleGenerateImage}
          onGenerateAll={handleGenerateAll}
        />
      )}

      <Assistant 
        isOpen={isAssistantOpen} 
        onClose={() => setIsAssistantOpen(false)}
        contextData={scenes}
      />
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type, Schema, GenerateContentResponse } from "@google/genai";
import { ScriptScene } from '../types';

// Ensure API key is available
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

declare const puter: any;

// --- Script Analysis ---

export const analyzeScript = async (scriptText: string): Promise<ScriptScene[]> => {
  if (!apiKey) throw new Error("API Key not found");

  const systemInstruction = `You are an expert storyboard artist and director. 
  Your task is to analyze a movie or video script and break it down into key visual frames.
  For each frame, extract the scene number (if implicit, count up), a short narrative description, and a highly detailed "visual_prompt" optimized for an AI image generator.
  The visual prompt must describe the composition, lighting, camera angle, subject, and style.
  Return the result as a JSON array.`;

  const schema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        scene_number: { type: Type.INTEGER },
        description: { type: Type.STRING },
        visual_prompt: { type: Type.STRING },
      },
      required: ["scene_number", "description", "visual_prompt"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Using Pro for better logic/reasoning on scripts
      contents: scriptText,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema,
      },
    });

    const jsonText = response.text;
    if (!jsonText) return [];

    const parsed = JSON.parse(jsonText);

    // Add client-side IDs and state
    return parsed.map((item: any, index: number) => ({
      id: `scene-${index}-${Date.now()}`,
      scene_number: item.scene_number,
      description: item.description,
      visual_prompt: item.visual_prompt,
      is_generating: false,
    }));

  } catch (error) {
    console.error("Analysis failed:", error);
    throw error;
  }
};

// --- Image Generation (Using Puter.js) ---

export const generateSceneImage = async (prompt: string): Promise<string | null> => {
  try {
    // Using Puter.js for unlimited image generation
    const imageElement = await puter.ai.txt2img(prompt);

    if (imageElement && imageElement.src) {
      return imageElement.src;
    }
    return null;
  } catch (error) {
    console.error("Image generation failed:", error);
    throw error;
  }
};

// --- Chat Assistant ---

export const sendChatMessage = async (history: {role: string, parts: {text: string}[]}[], newMessage: string, context?: string): Promise<string> => {
  if (!apiKey) throw new Error("API Key not found");

  const systemInstruction = `You are StoryBoard AI Assistant. You help users refine their scripts, suggest camera angles, and improve visual prompts. 
  ${context ? `Current Context: ${context}` : ''}
  Keep answers concise and helpful for visual storytelling.`;

  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction,
      },
      history: history.map(h => ({
        role: h.role,
        parts: h.parts
      }))
    });

    const result: GenerateContentResponse = await chat.sendMessage({
      message: newMessage
    });

    return result.text || "I couldn't generate a response.";
  } catch (error) {
    console.error("Chat failed:", error);
    return "Sorry, I encountered an error processing your request.";
  }
};

