import React, { useState, useRef, useEffect } from 'react';
import { Send, X, Bot, User } from 'lucide-react';
import { sendChatMessage } from '../services/geminiService';
import { ChatMessage, ScriptScene } from '../types';

interface AssistantProps {
  isOpen: boolean;
  onClose: () => void;
  contextData: ScriptScene[];
}

export const Assistant: React.FC<AssistantProps> = ({ isOpen, onClose, contextData }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hi! I can help you refine your script or suggest better visual prompts for your storyboard. What are you working on?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    // Prepare context
    const contextSummary = contextData.length > 0 
      ? `User has a storyboard with ${contextData.length} scenes. Scene 1 description: ${contextData[0].description}...` 
      : "User has not analyzed a script yet.";

    // Format history for API:
    // IMPORTANT: Exclude the first message (index 0) because it is a client-side hardcoded greeting.
    // The API expects history to typically start with a 'user' turn if provided.
    // We start slicing from index 1.
    const history = messages.slice(1).map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    try {
      const responseText = await sendChatMessage(history, userMsg.text, contextSummary);
      setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I encountered an error. Please try again." }]);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-y-0 right-0 w-full sm:w-96 bg-slate-900 border-l border-slate-700 shadow-2xl z-50 transform transition-transform duration-300 ease-in-out flex flex-col no-print">
      <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-800/50">
        <h3 className="font-semibold text-white flex items-center gap-2">
          <Bot className="w-5 h-5 text-indigo-400" />
          AI Assistant
        </h3>
        <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
          <X className="w-5 h-5" />
        </button>
      </div>

      <div className="flex-grow overflow-y-auto p-4 space-y-4">
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] rounded-2xl p-3 text-sm ${
                msg.role === 'user'
                  ? 'bg-indigo-600 text-white rounded-br-none'
                  : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
              }`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-800 rounded-2xl p-3 rounded-bl-none border border-slate-700 flex items-center gap-2">
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce delay-100" />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce delay-200" />
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 border-t border-slate-700 bg-slate-900">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask for suggestions..."
            className="w-full bg-slate-800 text-white rounded-full pl-4 pr-12 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-600 rounded-full text-white disabled:opacity-50 hover:bg-indigo-500 transition-colors"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type, Schema, GenerateContentResponse, Content } from "@google/genai";
import { ScriptScene } from '../types';

// Ensure API key is available
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

declare const puter: any;

// --- Script Analysis ---

export const analyzeScript = async (scriptText: string): Promise<ScriptScene[]> => {
  if (!apiKey) throw new Error("API Key not found");

  const systemInstruction = `You are an expert storyboard artist and director. 
  Your task is to analyze a movie or video script and break it down into key visual frames.
  For each frame, extract the scene number (if implicit, count up), a short narrative description, and a highly detailed "visual_prompt" optimized for an AI image generator.
  The visual prompt must describe the composition, lighting, camera angle, subject, and style.
  Return the result as a JSON array.`;

  const schema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        scene_number: { type: Type.INTEGER },
        description: { type: Type.STRING },
        visual_prompt: { type: Type.STRING },
      },
      required: ["scene_number", "description", "visual_prompt"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Using Pro for better logic/reasoning on scripts
      contents: scriptText,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema,
      },
    });

    const jsonText = response.text;
    if (!jsonText) return [];

    const parsed = JSON.parse(jsonText);

    // Add client-side IDs and state
    return parsed.map((item: any, index: number) => ({
      id: `scene-${index}-${Date.now()}`,
      scene_number: item.scene_number,
      description: item.description,
      visual_prompt: item.visual_prompt,
      is_generating: false,
    }));

  } catch (error) {
    console.error("Analysis failed:", error);
    throw error;
  }
};

